package jsjson

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"testing"
)

// nodeFixture is generated by testdata/gen_messages.mjs from the Node in PATH.
type nodeFixture struct {
	NodeVersion string `json:"nodeVersion"`
	Template    string `json:"template"`
	Cases       []struct {
		Input   string `json:"input"`
		Message string `json:"message"`
	} `json:"cases"`
}

func loadNodeFixture(t *testing.T) nodeFixture {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", "v8_errors.json"))
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	var fixture nodeFixture
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatalf("decode fixture: %v", err)
	}
	if len(fixture.Cases) == 0 {
		t.Fatal("fixture has no cases")
	}
	return fixture
}

// TestSyntaxErrorMessageMatchesNode asserts byte-for-byte parity with the
// JSON.parse SyntaxError.message text recorded from Node.
func TestSyntaxErrorMessageMatchesNode(t *testing.T) {
	fixture := loadNodeFixture(t)
	t.Logf("fixture generated with node %s (%d cases)", fixture.NodeVersion, len(fixture.Cases))
	for i, tc := range fixture.Cases {
		tc := tc
		t.Run(fmt.Sprintf("%03d", i), func(t *testing.T) {
			got := SyntaxErrorMessage(tc.Input)
			if got != tc.Message {
				t.Fatalf("input %q\n got: %q\nwant: %q", tc.Input, got, tc.Message)
			}
		})
	}
}

func TestValidJSONHasNoMessage(t *testing.T) {
	for _, input := range []string{
		"null", "true", "false", "0", "-0", "1.5e10", `"text"`, "[]", "{}",
		`{"a":[1,{"b":"c"}],"d":null}`, " \n\t[1,2,3] \r\n", `"\uD800"`,
		`"\ud83d\ude00"`, `"escaped \\ \" \/ \b \f \n \r \t"`, "123456789012345678901234567890",
	} {
		if got := SyntaxErrorMessage(input); got != "" {
			t.Errorf("input %q: got message %q, want none", input, got)
		}
	}
}
